mapper.sql:
where 1=1

    and res.contract_code = #{param.contractCode}





    and res.client_name like concat('%', #{param.clientName}::text, '%')


    and res.org_id = #{param.orgId}


    and res.outbound_type = #{param.outboundType}



    and res.inbound_date >= #{param.inboundDateStart}



    and res.inbound_date <= #{param.inboundDateEnd}



    and res.outbound_date >= #{param.outboundDateStart}



    and res.outbound_date <= #{param.outboundDateEnd}
